        'spell-range':  1.1,
        'spell-range-bg': 0.7,
        'spell-range-dmg': 1.05,
        'heal-range':   0.95,
        'spell-damage': 1.2,
        'heal':         1.2,
        'inspect':      0.8,
        'move ally':    0.9,
        'combo-target': 1.15,
        'selected':     0.35,
        'placeable':    0.85
