        var caustEmisC = (style && style.caustEmis) || 'vec3(0.25, 0.55, 0.55)';
        var glintColC  = (style && style.glintCol)  || 'vec3(0.85, 0.95, 1.0)';
        var hueShiftC  = (style && style.hueShift)  || 'vec3(0.92, 1.0, 1.1)';
