        if (Array.isArray(name)) {
            var picked = null;
            for (var ni = 0; ni < name.length; ni++) {
                if (ue.actions[name[ni]]) { picked = name[ni]; break; }
            }
            if (!picked) return false;
            name = picked;
        }
