        if (entry.beam && entry.beam.geometry) entry.beam.geometry.dispose();
        if (entry.glow && entry.glow.geometry) entry.glow.geometry.dispose();
        if (entry.dot && entry.dot.geometry) entry.dot.geometry.dispose();
