        // the doorway, warm with hearth-light — someone is home
        var doorMat = _hzGlowMat(0xffb868, 0.55);
        var door = new THREE.Mesh(new THREE.CircleGeometry(tunR * 0.8, 12, 0, Math.PI), doorMat);
