            var W = (typeof bw === 'function') ? bw() :
                    (state.boardTerrain[0] ? state.boardTerrain[0].length : 0);
            var H = (typeof bh === 'function') ? bh() : state.boardTerrain.length;
            if (!W || !H) { if (_miniWrap) _miniWrap.style.display = 'none'; return; }

            _ensureMinimap();
